import os, re, csv
from datetime import date, timedelta

LOGDIR = "/app/logs"
TODAY = date(2025, 8, 12)
SEVS = ["ERROR", "WARNING", "INFO"]

# day -> severity -> count
daily = {}
for fn in sorted(os.listdir(LOGDIR)):
    m = re.match(r"^(\d{4}-\d{2}-\d{2})_[^_]+\.log$", fn)
    if not m:
        continue
    y, mo, d = map(int, m.group(1).split("-"))
    dt = date(y, mo, d)
    if dt > TODAY:
        continue
    counts = daily.setdefault(dt, {s: 0 for s in SEVS})
    with open(os.path.join(LOGDIR, fn), encoding="utf-8", errors="replace") as fh:
        for line in fh:
            for s in SEVS:
                if ("[%s]" % s) in line:
                    counts[s] += 1

def count_in_range(start):
    total = {s: 0 for s in SEVS}
    for dt, c in daily.items():
        if start <= dt <= TODAY:
            for s in SEVS:
                total[s] += c[s]
    return total

def count_total():
    total = {s: 0 for s in SEVS}
    for c in daily.values():
        for s in SEVS:
            total[s] += c[s]
    return total

windows = [
    ("today", count_in_range(TODAY)),
    ("last_7_days", count_in_range(TODAY - timedelta(days=6))),
    ("last_30_days", count_in_range(TODAY - timedelta(days=29))),
    ("month_to_date", count_in_range(date(TODAY.year, TODAY.month, 1))),
    ("total", count_total()),
]

with open("/app/summary.csv", "w", newline="") as out:
    w = csv.writer(out)
    w.writerow(["period", "severity", "count"])
    for period, c in windows:
        for s in SEVS:
            w.writerow([period, s, c[s]])

print("Days found:", len(daily), "min:", min(daily), "max:", max(daily))
for period, c in windows:
    print(period, dict(c))
